export type ParsedOpenCardInstruction<
  TProgram extends string = typeof PENNY_POST_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>
  accounts: {
    recipient: TAccountMetas[0]
    sender: TAccountMetas[1]
    card: TAccountMetas[2]
    vault: TAccountMetas[3]
    recipientToken?: TAccountMetas[4] | undefined
    /**
     * open a card without ever opening a letterbox, so the handler loads it by
     * hand and skips the tally if there is none.
     */
    recipientLetterbox: TAccountMetas[5]
    postOffice: TAccountMetas[6]
    postageMint: TAccountMetas[7]
    tokenProgram: TAccountMetas[8]
  }
  data: OpenCardInstructionData
}

export function parseOpenCardInstruction<TProgram extends string, TAccountMetas extends readonly AccountMeta[]>(
  instruction: Instruction<TProgram> & InstructionWithAccounts<TAccountMetas> & InstructionWithData<ReadonlyUint8Array>,
): ParsedOpenCardInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 9) {
    throw new SolanaError(SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS, {
      actualAccountMetas: instruction.accounts.length,
      expectedAccountMetas: 9,
    })
  }
  let accountIndex = 0
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!
    accountIndex += 1
    return accountMeta
  }
  const getNextOptionalAccount = () => {
    const accountMeta = getNextAccount()
    return accountMeta.address === PENNY_POST_PROGRAM_ADDRESS ? undefined : accountMeta
  }
  return {
    programAddress: instruction.programAddress,
    accounts: {
      recipient: getNextAccount(),
      sender: getNextAccount(),
      card: getNextAccount(),
      vault: getNextAccount(),
      recipientToken: getNextOptionalAccount(),
      recipientLetterbox: getNextAccount(),
      postOffice: getNextAccount(),
      postageMint: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getOpenCardInstructionDataDecoder().decode(instruction.data),
  }
}
